#include <vector>
#include <algorithm>

class Solution {
public:
    int countDominantNodes(const std::vector<int>& vals) {
        int n = vals.size();
        if (n == 0) return 0;
        int ans = 0;
        long long INF = 1e18;
        auto dfs = [&](auto self, int idx) -> long long {
            if (idx >= n || vals[idx] == -1) return -INF;
            long long v = vals[idx];
            long long lMax = self(self, 2 * idx + 1);
            long long rMax = self(self, 2 * idx + 2);
            if (v > lMax && v > rMax) ans++;
            return std::max({v, lMax, rMax});
        };
        dfs(dfs, 0);
        return ans;
    }
};

class Solution {
    private int ans = 0;
    private long INF = (long)1e18;

    public int countDominantNodes(int[] vals) {
        ans = 0;
        if (vals == null || vals.length == 0) return 0;
        dfs(0, vals);
        return ans;
    }

    private long dfs(int idx, int[] vals) {
        if (idx >= vals.length || vals[idx] == -1) return -INF;
        long v = vals[idx];
        long lMax = dfs(2 * idx + 1, vals);
        long rMax = dfs(2 * idx + 2, vals);
        if (v > lMax && v > rMax) ans++;
        return Math.max(v, Math.max(lMax, rMax));
    }
}

function countDominantNodes(rootVals) {
    if (!rootVals || rootVals.length === 0 || rootVals[0] === null) return 0;
